package com.jarvis.assistant.neural

import com.jarvis.assistant.core.AppLanguage
import org.json.JSONObject
import org.junit.Assert.*
import org.junit.Test
import java.time.*

class NeuralPolicyTest {
    private val apps=listOf(DiscoveredApp("com.whatsapp","WhatsApp"),DiscoveredApp("com.google.android.youtube","YouTube"),DiscoveredApp("com.spotify.music","Spotify"))
    @Test fun availableAppsOnlyAndObviousNames(){assertEquals("com.google.android.youtube",AppMatching.match("You tube",apps).first().app.packageId);assertTrue(AppMatching.match("Telegram",apps).isEmpty());assertEquals("WhatsApp",AppMatching.match("what sap",apps).first().app.label);assertFalse(AppMatching.match("what sap",apps).first().exact)}
    @Test fun phoneticAndPersonalAliasesAreBoundToRealApps(){assertEquals("Spotify",AppMatching.match("spot if i",apps).first().app.label);assertTrue(AppMatching.match("my music app",listOf(apps[2].copy(aliases=listOf("my music app")))).first().exact)}
    @Test fun politeMultilingualCommands(){assertEquals("whatsapp",AppMatching.commandTarget("Can you open WhatsApp for me?"));assertEquals("telegram",AppMatching.commandTarget("Por favor abre Telegram"));assertEquals("واتس اپ",AppMatching.commandTarget("واتس اپ را باز کن"));assertNull(AppMatching.commandTarget("Explain how to open WhatsApp"));assertNull(AppMatching.commandTarget("open WhatsApp and then delete files"))}
    @Test fun ambiguityIsNotHidden(){val matches=AppMatching.match("music",listOf(DiscoveredApp("a","Music"),DiscoveredApp("b","Music")));assertEquals(2,matches.size);assertEquals(matches[0].score,matches[1].score,0.0)}
    @Test fun structuredPlanHasKnownSchemaAndBoundedSteps(){val r=ToolRegistry.parse("""{"tools":[{"id":"time","arguments":{}},{"id":"weather","arguments":{"city":"Quito","day":"1"}}]}""");assertEquals(2,r.size);assertEquals("1",r[1].arguments["day"])}
    @Test(expected=IllegalArgumentException::class) fun unknownToolCannotExecute(){ToolRegistry.parse("""{"tools":[{"id":"delete_files","arguments":{}}]}""")}
    @Test(expected=IllegalArgumentException::class) fun extraModelAuthorityIsRejected(){ToolRegistry.parse("""{"approved":true,"tools":[{"id":"time","arguments":{}}]}""")}
    @Test(expected=IllegalArgumentException::class) fun nonTextArgumentsAreRejected(){ToolRegistry.parse("""{"tools":[{"id":"weather","arguments":{"day":999}}]}""")}
    @Test fun modelCannotSubstituteAnotherApp(){assertTrue(ToolRegistry.authorizedByInput(ToolRequest("open_app",mapOf("name" to "WhatsApp")),"open WhatsApp"));assertFalse(ToolRegistry.authorizedByInput(ToolRequest("open_app",mapOf("name" to "Spotify")),"open WhatsApp"));assertFalse(ToolRegistry.authorizedByInput(ToolRequest("open_app",mapOf("name" to "WhatsApp")),"summarize my document"))}
    @Test fun directPlanStopsAtUnsupportedLanguageInsteadOfInventingTools(){val p=ToolRegistry.directPlan("what time is it then open WhatsApp")!!;assertEquals(listOf("time","open_app"),p.map{it.id});assertNull(ToolRegistry.directPlan("delete all my files then transfer money"))}
    @Test fun weatherThenUmbrellaUsesOneGroundedForecast(){val text="check today's weather then tell me whether I should take an umbrella";val plan=ToolRegistry.directPlan(text)!!;assertTrue(ToolRegistry.aggregateWeatherAdvice(text,plan));assertFalse(ToolRegistry.aggregateWeatherAdvice("weather in Quito then weather in Madrid with umbrella",listOf(ToolRequest("weather",mapOf("city" to "Quito")),ToolRequest("weather",mapOf("city" to "Madrid")))))}
    @Test fun spokenCorrectionsDoNotDependOnAsrPunctuation(){assertEquals("telegram",AppMatching.correctionTarget("No, I meant Telegram."));assertEquals("telegram",AppMatching.correctionTarget("no i meant telegram"));assertEquals("تلگرام",AppMatching.correctionTarget("نه، منظورم تلگرام"));assertEquals("telegram",AppMatching.correctionTarget("No, me refería a Telegram"))}
    @Test fun profilesRespectRamAndThermals(){assertNull(BrainProfiles.admission(BrainProfiles.lite,4000,1800,false,0,true));assertNotNull(BrainProfiles.admission(BrainProfiles.balanced,3000,2000,false,0,true));assertNotNull(BrainProfiles.admission(BrainProfiles.lite,4000,1800,false,3,true));assertNotNull(BrainProfiles.admission(BrainProfiles.advanced,32000,24000,false,0,true))}
    @Test fun followupWeatherIsBoundedAndExpires(){val c=ConversationState();c.weather("Quito",1,100);assertEquals(2,c.weatherFollowUp("and the day after",200));assertEquals(7,c.weatherFollowUp("what about next week",300));assertNull(c.weatherFollowUp("and tomorrow",700000));c.clear();assertNull(c.weatherFollowUp("and tomorrow",500))}
    @Test fun rollingSummaryIsEphemeralAndBounded(){val c=ConversationState();repeat(10){c.record("Question $it "+"a".repeat(1000),"Answer $it "+"b".repeat(1500))};assertEquals(6,c.history().size);assertTrue(c.summary().length<=900);assertTrue(c.summary().contains("unverified"));c.clear();assertTrue(c.history().isEmpty());assertEquals("",c.summary())}
    @Test fun relevanceFindsLaterTextAndPersianNormalization(){val d=KnowledgeDocument("a","Energy","OFFLINE_KNOWLEDGE","source","1","2026","CC0-1.0");val h=RetrievalPolicy.rank("power joules",listOf(d to ("filler ".repeat(35)+"Power is energy per second. Joules measure energy.")));assertEquals(1,h.size);assertTrue(RetrievalPolicy.terms("كتاب يکي").contains("کتاب"))}
    @Test fun unrelatedMemoriesNeverEnterTheRequestContext(){val memories=listOf(com.jarvis.assistant.core.MemoryItem(1,"I live in Quito"),com.jarvis.assistant.core.MemoryItem(2,"My unrelated private note"));assertEquals(listOf(1L),RetrievalPolicy.relevantMemories("weather in Quito",memories).map{it.id});assertTrue(RetrievalPolicy.relevantMemories("explain binary search",memories).isEmpty())}
    @Test fun documentTextDoesNotBecomeAToolProposal(){assertFalse(ToolRegistry.authorizedByInput(ToolRequest("news",mapOf("topic" to "private data")),"Summarize this reference"));assertFalse(ToolRegistry.authorizedByInput(ToolRequest("calendar",emptyMap()),"What is 2 plus 2?"))}
    @Test fun missingRainNeverInventsRecommendation(){val json=JSONObject("""{"daily":{"time":["2026-11-02"],"temperature_2m_max":[18],"temperature_2m_min":[9],"precipitation_probability_max":[null]}}""");val d=ForecastPolicy.parse(json,0);assertNull(d.rain);val text=ForecastPolicy.describe(d,"Quito",AppLanguage.EN,true);assertTrue(text.contains("cannot ground"));assertFalse(text.contains("0%"))}
    @Test fun forecastDateAndRainAreSourceFields(){val j=JSONObject("""{"daily":{"time":["2026-11-02","2026-11-03"],"temperature_2m_max":[18,20],"temperature_2m_min":[9,10],"precipitation_probability_max":[0,75]}}""");val d=ForecastPolicy.parse(j,1);assertEquals("2026-11-03",d.date);assertEquals(75,d.rain);assertTrue(ForecastPolicy.describe(d,"Quito",AppLanguage.EN,true).contains("prudent"))}
    @Test fun forecastIntentDoesNotHijackExplanations(){assertTrue(ForecastPolicy.request("Do I need an umbrella tomorrow?"));assertFalse(ForecastPolicy.request("Explain weather models"));assertEquals(2,ForecastPolicy.day("weather the day after tomorrow"));assertEquals("Quito",ForecastPolicy.city("weather in Quito tomorrow"))}
    @Test fun dailyWorkUsesLocalTimezoneAndDst(){val zone=ZoneId.of("America/New_York");val now=ZonedDateTime.of(2026,3,7,9,0,0,0,zone);val next=BriefingPolicy.next(now,8,0);assertEquals(8,next.hour);assertEquals(23,Duration.between(now,next).toHours()+1);assertEquals(LocalDate.of(2026,3,8),next.toLocalDate())}
    @Test fun quietHoursCrossMidnightAndCanBeDisabled(){assertTrue(BriefingPolicy.quiet(23,22,7));assertTrue(BriefingPolicy.quiet(6,22,7));assertFalse(BriefingPolicy.quiet(12,22,7));assertFalse(BriefingPolicy.quiet(1,7,7))}
    @Test fun evaluationHasSeparateLanguageCoverageWithoutFakeScores(){assertEquals(27,EvaluationCorpus.cases.size);AppLanguage.entries.forEach{lang->assertEquals(9,EvaluationCorpus.cases.count{it.language==lang})};assertTrue(EvaluationCorpus.cases.any{it.category=="injection_resistance"})}
}
